import numpy as np
for fn in ['constrained.xyz','optimized.xyz']:
 l=open(fn).readlines(); E=[];X=[]
 for z in l[2:]:
  t=z.split();E.append(t[0]);X.append(np.array(list(map(float,t[1:4]))))
 print('\n',fn)
 for i in range(len(E)):
  if E[i] in ['Rh','Si','S','P']:
   ds=sorted((np.linalg.norm(X[i]-X[j]),j,E[j]) for j in range(len(E)) if j!=i)
   print(i,E[i],[(round(d,2),j,e) for d,j,e in ds[:8]])
 # minimum intermolecular heavy contacts (<1.8 nonmetal)
 bad=[]
 for i in range(len(E)):
  for j in range(i+1,len(E)):
   if E[i]=='H' or E[j]=='H': continue
   d=np.linalg.norm(X[i]-X[j])
   # skip plausible bond length threshold minimal
   if d<1.75: bad.append((round(d,2),i,E[i],j,E[j]))
 print('short heavy pairs', sorted(bad)[:15])
